import{_ as r,a0 as i,w as s,s as m,ao as p,I as o,a1 as a,A as n,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"直击 Elementart OS 0.3 Freya - 下载和安装指南 | LCTT x X-CMD","titleTemplate":false,"description":"直击 Elementart OS 0.3 Freya - 下载和安装指南 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"直击 Elementart OS 0.3 Freya - 下载和安装指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"直击 Elementart OS 0.3 Freya - 下载和安装指南 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150413 Elementary OS 0.3 Freya Screenshots - Download and Install Guide","title":"直击 Elementart OS 0.3 Freya - 下载和安装指南","tag":"201504","desc":""},"relativePath":"201504/20150413 Elementary OS 0.3 Freya Screenshots - Download and Install Guide.md","filePath":"[post].md"}'),d={name:"201504/20150413 Elementary OS 0.3 Freya Screenshots - Download and Install Guide.md"};function u(g,t,y,S,f,b){const l=i("Link");return s(),m("div",null,[t[18]||(t[18]=p('<h1 id="直击-elementart-os-0-3-freya-下载和安装指南" tabindex="-1">直击 Elementart OS 0.3 Freya - 下载和安装指南 <a class="header-anchor" href="#直击-elementart-os-0-3-freya-下载和安装指南" aria-label="Permalink to “直击 Elementart OS 0.3 Freya - 下载和安装指南”">​</a></h1><p>Elementary OS是一个以Ubuntu为基础的轻量级操作系统，广受欢迎。目前已经发行了三个版本，而第四个版本将会以即将到来的Ubuntu16.04为基础开发。</p><ul><li><strong>Jupiter (0.1)</strong>: 第一个Elementary OS稳定发行版基于Ubuntu 10.10，在2011年三月发布。</li><li><strong>Luna (0.2)</strong>: Elementary OS第二个稳定发行版基于Ubuntu 12.04，于2012年11月发布。</li><li><strong>Freya (0.3)</strong>: Elementary OS第三个稳定发行版基于Ubuntu 14.04的，2015年二月8号发布。</li><li><strong>Loki (0.4)</strong>: 未来Elementary OS第四版，计划以Ubuntu16.04为基础，并且提供更新服务直到2021年。</li></ul><p>Freya是目前最新的Elementary OS版本（0.3）。最初是被命名为ISIS，但是后来改了，是为了避免与同名的恐怖组织产生任何的联系。Freya有一些非常不错的预装应用。</p><h3 id="突出的特性" tabindex="-1">突出的特性 <a class="header-anchor" href="#突出的特性" aria-label="Permalink to “突出的特性”">​</a></h3><p>这里列举了一些特性，但并非Elementary OS 0.3的所有特性。</p><ul><li>更好的交互性消息通知，可在通知设定面板设定系统级别的“Do Not Disturb（不要打扰）”模式。</li><li>最新版Elementary OS提供更好的emoji表情支持，及内置替换了网页应用中的微软核心字体。</li><li>Privacy模式是一个新的防火墙工具，易于使用，可以帮助保护电脑免遭恶意脚本和应用的攻击。</li><li>统一风格的登入和锁定界面。</li><li>改进了界面效果和功能的应用中心菜单，包括快速操作列表，搜索拖放，支持快速数学计算。</li><li>重新设计的多任务视图提供更多以应用为中心的功能。</li><li>更新了软件栈（Linux 3.16， Gtk 3.14 和Vala 0.26），更好的支持和增强了最新开发的应用。</li><li>UEFI支持。</li><li>通过新的联网助手，WiFi连接变得更容易。</li></ul><h3 id="下载64位-32位版本" tabindex="-1">下载64位&amp;32位版本 <a class="header-anchor" href="#下载64位-32位版本" aria-label="Permalink to “下载64位&amp;32位版本”">​</a></h3>',8)),o("ul",null,[o("li",null,[a(l,{href:"http://sourceforge.net/projects/elementaryos/files/stable/elementaryos-freya-amd64.20150411.iso/download"},{default:n(()=>[...t[0]||(t[0]=[e("Elementary OS Freya 64 bit",-1)])]),_:1})]),o("li",null,[a(l,{href:"http://sourceforge.net/projects/elementaryos/files/stable/elementaryos-freya-i386.20150411.iso/download"},{default:n(()=>[...t[1]||(t[1]=[e("Elementary OS Freya 32 bit",-1)])]),_:1})])]),t[19]||(t[19]=p(`<h3 id="安装elementary-os-0-3-freya" tabindex="-1">安装Elementary OS 0.3 (Freya) <a class="header-anchor" href="#安装elementary-os-0-3-freya" aria-label="Permalink to “安装Elementary OS 0.3 (Freya)”">​</a></h3><p>下载Elementary OS 0.3的ISO文件，并且写入到一个USB启动盘或者DVD/CD。支持32位和64位的架构。当计算机从Elementary OS ISO文件启动后，有两个选项可用，或不安装而仅试用，或直接安装到计算机里。这里选择第二项。Elmentary OS也可以与已有操作系统并存安装，构成双重启动。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Install-Freya.png" alt="Install Freya"></p><p>在进行下面的步骤之前会检查系统要求和资源有效性。如果你的系统有足够的资源，点击继续。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-Requirements.png" alt="Installation Requirements"></p><p>安装向导提供许多安装形式。选取最适合你的选项，通常大多数都选用第一个选项：“擦除磁盘以安装Elementary”。选择该选项，必须保证你的原有数据都已经正确备份了，因为磁盘（分区）将会被擦除，其上所有的数据将会丢失。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-Types.png" alt="Installation Types"></p><p>接下来的对话框显示了Elementary OS所使用和需要格式化的磁盘分区列表，确保数据完整后点击继续。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Format-Warning.png" alt="Format Warning"></p><p>选择你的地理位置，确定时区，点击继续。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Location.png" alt="Location"></p><p>选择你的语言，点击继续。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Language.png" alt="Language"></p><p>填入你的信息，选择一个高强度的超级用户/管理员密码，点击继续。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/whoareyou.png" alt="whoareyou"></p><p>当你的信息提供后，核心安装进程就会启动，正在安装的组件的详细信息会在一个小对话框里随进度条一闪而过。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-progress.png" alt="Installation progress"></p><p>恭喜你！最新的Elementary OS 0.3 (Freya)已经安装完成了。此时需要重启来更新和完整注册，恭喜。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-Complet.png" alt="Installation Complet"></p><p>启动时，Elementary OS将显示它优雅的logo，然后会出现密码保护的管理员登入和游客访问选项。游客访问有相当多的限制功能，而且没有安装软件的权限。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Login.png" alt="Login"></p><p>下图是新安装的Elementary OS 0.3的画面。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/first-look.png" alt="first look"></p><h3 id="个性化桌面" tabindex="-1">个性化桌面 <a class="header-anchor" href="#个性化桌面" aria-label="Permalink to “个性化桌面”">​</a></h3><p>Elementary OS 0.3以其轻巧和美观而为我们熟知，每个人有自己独特的审美观和计算机使用习惯。桌面反映出每一个计算机使用者的个人偏好。如其他操作系统一样，Elementary OS 0.3也提供了许多选项来个性化配置桌面，包括壁纸，字体大小，主题等等。</p><p>基本的个性化配置，点击Applications &gt; System Settings &gt; Desktop</p><p>我们可以改变壁纸，泊板（dock）和启用桌面热角。</p><p>默认提供了很少的壁纸，更多的可以从网上下载或者从你的相机传输过来。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Desktop-Wallpaper4.png" alt="Desktop Wallpaper"></p><p>Elementary OS真正的美丽在于优雅的泊板。桌面上没有任何图标，泊板上的应用图标显示逼真，通过它可以快速访问常用应用。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Desktop-Dock1.png" alt="Desktop Dock"></p><p>用户可以定制桌面的四个角的功能。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Hot-Corners.png" alt="Hot Corners"></p><p>通过安装elementary tweaks工具来更深入的个性化定制。</p><p>可以使用如下命令，将稳定的个人软件包档案（PPA）添加到高级软件包管理工具（APT）仓库。</p><pre><code>sudo add-apt-repository ppa:mpstark/elementary-tweaks-daily
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/elementary-tweaks-ppa.png" alt="ppa"></p><p>一旦软件包添加到仓库后，我们需要用以下命令更新仓库</p><pre><code>sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/update-repository.png" alt="update repository"></p><p>更新仓库后，我们就可以安装elementary-tweaks，用以下命令完成</p><pre><code>sudo apt-get install elementary-tweaks
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/install-elementary-tweaks.png" alt="install elementary tweaks"></p><p>我们可以在Application &gt; System Settings下的个人区域的看到增加了一个Tweaks项目。它现在可以给我们提供更多的个性化定制选项。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/tweaks.png" alt="tweaks"></p><p>为了进一步定制，我们也安装了gnome桌面系统的tweak工具，演示解锁桌面。</p><pre><code>sudo apt-get install gnome-tweak-tool
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/gnome.png" alt="gnome"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,49)),o("p",null,[t[3]||(t[3]=e("Elementary OS十分接近Linux发行版Ubuntu，它的优缺点两方面也都十分相似。Elementary OS在外观和体验上都十分轻巧和优雅，并且正在快速地走向成熟。它有潜力成为Windows和OS X操作系统之外的第三选择。最新的Elementary OS 0.3（Freya）以其良好的功能基础而迅速流行。想了解更多信息，最近的更新和下载，请访问其官方",-1)),a(l,{href:"http://sourceforge.net/projects/elementaryos/files/stable/elementaryos-freya-amd64.20150411.iso/download"},{default:n(()=>[...t[2]||(t[2]=[e("网站",-1)])]),_:1}),t[4]||(t[4]=e("。",-1))]),t[20]||(t[20]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),a(l,{href:"http://linoxide.com/ubuntu-how-to/elementary-os-0-3-freya-install-guide/"},{default:n(()=>[...t[5]||(t[5]=[e("http://linoxide.com/ubuntu-how-to/elementary-os-0-3-freya-install-guide/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),a(l,{href:"http://linoxide.com/author/arunrz/"},{default:n(()=>[...t[7]||(t[7]=[e("Aun Raza",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),a(l,{href:"https://github.com/wi-cuckoo"},{default:n(()=>[...t[8]||(t[8]=[e("wi-cuckoo",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),a(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创翻译，",-1)),a(l,{href:"http://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const x=r(d,[["render",u]]);export{h as __pageData,x as default};
